@startuml

class Customer {
  + name : string
  + phoneNumber : string
}

class Table {
  + numberOfSeats : int
  + isSmoking : boolean
}

class Reservation {
  + reservationDay : date
  + reservationTime : time
  + numberOfPeople : int
}

class Waiter {
  + name : string
  + yearsOfService : int
}

class Bill {
  + finalAmount : double
}

class Dish {
  + name : string
  + unitPrice : double
}

Customer "1" -- "0..*" Reservation : makes
Reservation "1" -- "1..*" Table : assigns
Waiter "1" -- "0..*" Table : serves
Waiter "1" -- "0..*" Customer : serves
Customer "1" -- "0..*" Bill : pays
Bill "1" *-- "1..*" Dish : contains

@enduml

